-- ClinicSaathi MySQL schema (generated by `npm run db:schema` from server/src/models).
-- Run in MySQL Workbench, or let the API create these tables itself on first start.

CREATE DATABASE IF NOT EXISTS `clinicsaathi` CHARACTER SET utf8mb4 COLLATE utf8mb4_bin;
USE `clinicsaathi`;

-- User
CREATE TABLE IF NOT EXISTS `users` (
  `id` CHAR(24) NOT NULL,
  `name` TEXT NULL,
  `email` VARCHAR(191) NULL,
  `phone` VARCHAR(191) NULL,
  `passwordHash` TEXT NULL,
  `role` TEXT NULL,
  `clinicId` CHAR(24) NULL,
  `branchId` CHAR(24) NULL,
  `doctorId` CHAR(24) NULL,
  `patientId` CHAR(24) NULL,
  `isActive` TINYINT(1) NULL,
  `lastLoginAt` DATETIME(3) NULL,
  `refreshTokenHash` TEXT NULL,
  `passwordReset` JSON NULL,
  `failedLogins` DOUBLE NULL,
  `lockedUntil` DATETIME(3) NULL,
  `invitedByUserId` CHAR(24) NULL,
  `createdAt` DATETIME(3) NULL,
  `updatedAt` DATETIME(3) NULL,
  `uq_key_0` VARCHAR(600) GENERATED ALWAYS AS (IF(`email` IS NOT NULL, CONCAT_WS('|', IFNULL(`email`, '~'), IFNULL(`clinicId`, '~')), NULL)) STORED,
  PRIMARY KEY (`id`),
  KEY `ix_users_email` (`email`),
  KEY `ix_users_phone` (`phone`),
  KEY `ix_users_clinicId` (`clinicId`),
  KEY `ix_users_branchId` (`branchId`),
  UNIQUE KEY `uq_users_0` (`uq_key_0`),
  KEY `ix_users_1` (`phone`, `clinicId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Clinic
CREATE TABLE IF NOT EXISTS `clinics` (
  `id` CHAR(24) NOT NULL,
  `name` TEXT NULL,
  `slug` VARCHAR(191) NULL,
  `tagline` TEXT NULL,
  `about` TEXT NULL,
  `logoUrl` TEXT NULL,
  `email` TEXT NULL,
  `phone` TEXT NULL,
  `gstin` TEXT NULL,
  `address` JSON NULL,
  `timings` JSON NULL,
  `holidays` JSON NULL,
  `bookingPolicy` JSON NULL,
  `notificationSettings` JSON NULL,
  `reviewUrl` TEXT NULL,
  `patientInfo` JSON NULL,
  `channels` JSON NULL,
  `festivals` JSON NULL,
  `integrations` JSON NULL,
  `onboarding` JSON NULL,
  `isActive` TINYINT(1) NULL,
  `createdAt` DATETIME(3) NULL,
  `updatedAt` DATETIME(3) NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_clinics_slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

