  `createdAt` DATETIME(3) NULL,
  `updatedAt` DATETIME(3) NULL,
  `uq_key_0` VARCHAR(600) GENERATED ALWAYS AS (IF(TRUE, CONCAT_WS('|', IFNULL(`clinicId`, '~'), IFNULL(`doctorId`, '~'), IFNULL(`queueDate`, '~'), IFNULL(CAST(`sequence` AS CHAR), '~')), NULL)) STORED,
  `uq_key_1` VARCHAR(600) GENERATED ALWAYS AS (IF(TRUE, CONCAT_WS('|', IFNULL(`clinicId`, '~'), IFNULL(`appointmentId`, '~')), NULL)) STORED,
  PRIMARY KEY (`id`),
  KEY `ix_queue_tokens_doctorId` (`doctorId`),
