  `uq_key_0` VARCHAR(600) GENERATED ALWAYS AS (IF(`status` IN ('DUE', 'NOTIFIED'), CONCAT_WS('|', IFNULL(`clinicId`, '~'), IFNULL(`patientId`, '~'), IFNULL(`serviceId`, '~')), NULL)) STORED,
  PRIMARY KEY (`id`),
  KEY `ix_recalls_patientId` (`patientId`),
  KEY `ix_recalls_dueDate` (`dueDate`),
  KEY `ix_recalls_status` (`status`),
  KEY `ix_recalls_clinicId` (`clinicId`),
  KEY `ix_recalls_branchId` (`branchId`),
  UNIQUE KEY `uq_recalls_0` (`uq_key_0`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;

-- Campaign
